INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 7, 'theory', 'Quiz: IOMMU, VFIO and SR-IOV');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 7, 0, 'What threat makes the IOMMU mandatory for device passthrough?', '["The device reads and writes memory directly (DMA) and can reach someone else''s memory", "The device is too fast", "The guest forgets its drivers", "There aren''t enough PCIe ports"]', 0, 'The device bypasses the processor and nested tables and uses the addresses given by the guest driver. The IOMMU translates and checks them.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 7, 1, 'What is an IOMMU group?', '["A set of virtual machines", "Devices that the IOMMU cannot isolate from each other, so they are handed over together", "A group of processors", "A set of disk images"]', 1, 'If a bridge does not isolate devices, the IOMMU sees them as one, and VFIO has to hand over the whole group.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 7, 2, 'What price is paid for device passthrough?', '["Speed is lost", "A second hypervisor is needed", "The network disappears", "Memory is pinned, there is no live migration or overcommit, and the machine is tied to a server"]', 3, 'Pinned pages cannot be evicted, ballooned or merged, and the state of real hardware is hard to move.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 7, 3, 'What is SR-IOV?', '["A way to encrypt traffic", "A migration protocol", "A device presents one physical function and many lightweight virtual ones, which are given to different machines", "A disk image format"]', 2, 'Each virtual function looks like a separate PCIe device with its own queues; the card itself does the switching.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 7, 4, 'What does interrupt remapping provide?', '["Speeds up disk I/O", "Uses a table to check which device may send interrupts to which vCPU, and drops foreign ones", "Disables the guest''s interrupts", "Compresses the device''s traffic"]', 1, 'This way a device in a guest cannot trigger someone else''s interrupt; allowed ones are delivered to the running guest without an exit.');
